window.AUTH=window.AUTH||{};window.AUTH["19-1155"]={"d":"19-1155","id":"2020/19-1155","n":"Garland v. Dai","briefs":[{"k":"petitioner","label":"Brief of petitioner William P. Barr, Attorney General","date":"2020-11-16","url":"https://www.supremecourt.gov/DocketPDF/19/19-1155/160906/20201116213730643_19-1155tsUnitedStates.pdf","side":"pet","n":45},{"k":"respondent","label":"Brief of respondent Cesar Alcaraz-Enriquez","date":"2021-01-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-1155/165294/20210104143300718_Alcaraz%20Brief.pdf","side":"res","n":94},{"k":"respondent","label":"Brief of respondent Ming Dai","date":"2021-01-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-1155/165339/20210104163200106_Dai%20Respondent%20Brief%20--%20FINAL.pdf","side":"res","n":24},{"k":"reply","label":"Reply of petitioner Robert M. Wilkinson, Acting Attorney General","date":"2021-02-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-1155/168081/20210203202829740_19-1155rbUnitedStates.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/20pdf/593us2r41_9o6b.pdf","tr":true,"items":[{"t":"case","label":"Allentown Mack Sales & Service, Inc. v. National Labor Relations Board","cite":"522 U.S. 359","y":1998,"id":"1997/96-795","sc":1,"sum":"The Court held that \"the Board's 'reasonable doubt' test for employer polls is facially rational and consistent with the Act.\" However, in a separate 5-4 split, the Court held that \"the Board's factual finding that Allentown Mack Sales lacked such a doubt is not supported by substantial evidence on the record as a whole.\" Justice Scalia wrote, \"the Board must be required to apply in fact the clearly understood legal standards that it enunciates in principle, such as good-faith reasonable doubt....Reviewing courts are entitled to take those standards to mean what they say, and to conduct substantial-evidence review on that basis.","sumSrc":"Oyez","by":{"0":"22","1":"passim","3":"10"}},{"t":"case","label":"Anaya-Ortiz v. Holder","cite":"594 F.3d 673","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/594/673/","by":{"0":"18, 26","1":"13"}},{"t":"case","label":"Banks v. Chicago Grain Trimmers Assn.","cite":"390 U.S. 459","y":1968,"id":"1967/59","sc":1,"op":1,"sum":"Petitioner filed a claim against her late husband's employer for compensation death benefits under the Longshoremen's and Harbor Workers' Compensation Act, alleging that his fall at home on January 30, 1961, from which he later died, resulted from a work-connected injury sustained on January 26. A Department of Labor Deputy Commissioner rejected the claim for failure to establish a work-connected injury. Thereafter, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22","3":"11"}},{"t":"case","label":"Bare v. Barr","cite":"975 F.3d 952","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/952/","by":{"0":"24"}},{"t":"case","label":"Biestek v. Berryhill","cite":"139 S. Ct. 1148","y":2019,"id":"2018/17-1184","sc":1,"sum":"A vocational expert’s refusal to provide private market-survey data during a Social Security disability benefits hearing upon the applicant’s request does not categorically preclude the testimony from counting as “substantial evidence” in federal court under 42 U. S. C. §405(g).","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29","1":"passim","2":"33"}},{"t":"case","label":"City of Canton v. Harris","cite":"489 U.S. 378","y":1989,"id":"1988/86-1088","sc":1,"sum":"The Court held that municipalities may be liable for inadequate training of employees, but only when “the failure to train amounts to deliberate indifference” to the constitutional rights of the people with whom the employees will interact. A municipality is then only liable when the failure to train is a deliberate choice on the part of the city.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Director, Office of Workers’ Compensation Programs, v. Greenwich Collieries","cite":"512 U.S. 267","y":1994,"id":"1993/93-744","sc":1,"op":1,"sum":"In adjudicating separate benefits claims under the Black Lung Benefits Act (BLBA) and the Longshore and Harbor Workers' Compensation Act (LHWCA), the Department of Labor Administrative Law Judges (AlJ's) both applied the Department's \"true doubt\" rule. This rule essentially shifts the burden of persuasion to the party opposing the claim so that when, as here, the evidence is evenly balanced, the benefits claimant …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21, 34","1":"passim"}},{"t":"case","label":"Doe v. Holder","cite":"651 F.3d 824","y":2011,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/651/824/","op":1,"by":{"0":"32","1":"39"}},{"t":"case","label":"Franchise Tax Board v. Hyatt","cite":"139 S. Ct. 1485","y":2019,"id":"2018/17-1299","sc":1,"sum":"Nevada v. Hall, 440 U. S. 410, is overruled; States retain their sovereign immunity from private suits brought in courts of other States.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Gonzales v. Thomas","cite":"547 U.S. 183","y":2006,"id":"2005/05-552","sc":1,"sum":"The Court held that an appellate court cannot substitute its judgment for that of the appropriate administrative agency on matters over which the agency has statutory authority.","sumSrc":"Oyez","by":{"0":"12, 20, 35, 36, 38","2":"26, 27, 46, 47","3":"19"}},{"t":"case","label":"Hu v. Holder","cite":"652 F.3d 1011","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/652/1011/","op":1,"sum":"Holding that unless the Board makes “an explicit adverse credibility finding, we assume that the facts in [the alien’s testimony] are true”.","sumSrc":"brief:0","by":{"0":"26, 27","3":"7"}},{"t":"case","label":"INS v. Cardoza-Fonseca","cite":"480 U.S. 421","y":1987,"id":"1986/85-782","sc":1,"sum":"The §243(h) \"clear probability\" standard of proof does not govern asylum applications under §208(a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","1":"4"}},{"t":"case","label":"INS v. Elias-Zacarias","cite":"502 U.S. 478","y":1992,"id":"1991/90-1342","sc":1,"op":1,"sum":"A guerrilla organization's attempt to coerce a person into performing military service does not necessarily constitute \"persecution on account of... political opinion\" under § 101(a)(42) of the Immigration and Nationality Act, 8 U. S. C. §1101(a)(42). Even one who supports the political aims of a guerrilla movement might resist military combat and thus become the object of such coercion. Moreover, persecution on …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 20, 21, 22"}},{"t":"case","label":"INS v. Orlando Ventura","cite":"537 U.S. 12","y":2002,"id":"2002/02-29","sc":1,"sum":"The Court held that an appellate court should generally remand a case to an agency when the subject matter is one over which the agency has authority pursuant to a statute.","sumSrc":"Oyez","by":{"0":"passim","1":"48","2":"11, 26, 27, 33, 46, 47, 50","3":"18, 22"}},{"t":"case","label":"Kalubi v. Ashcroft","cite":"364 F.3d 1134","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/364/1134/","by":{"0":"10, 16, 26, 27","1":"38","3":"2"}},{"t":"case","label":"Nasrallah v. Barr","cite":"140 S. Ct. 1683","y":2020,"id":"2019/18-1432","sc":1,"op":1,"sum":"The Court held that the federal courts have jurisdiction to review an administrative agency’s factual findings underlying denials of withholding (and deferral) of removal relief, notwithstanding 8 U.S.C. § 1252(a)(2)(C), which seems to divest courts of jurisdiction in such cases.","sumSrc":"Oyez","by":{"0":"20","1":"1, 7, 14, 29"}},{"t":"case","label":"Navas v. INS","cite":"217 F.3d 646","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/217/646/","by":{"0":"10, 16, 26, 27","1":"38","3":"7"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31","1":"32, 33"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"332 U.S. 194","y":1947,"id":"scdb/1946-133","sc":1,"sum":"The new order is sustained. Pp. 196-199, 209.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","1":"18, 19, 25, 47"}},{"t":"case","label":"Vermont Yankee Nuclear Power Corp. v. Natural Resources Defense Council, Inc.","cite":"435 U.S. 519","y":1978,"id":"1977/76-419","sc":1,"op":1,"sum":"In No. 76-419, after extensive hearings before the Atomic Safety and Licensing Board (Licensing Board) and over respondents' objections, the Atomic Energy Commission (AEC) granted petitioner Vermont Yankee Nuclear Power Corp. a license to operate a nuclear power plant, and this ruling was affirmed by the Atomic Safety and Licensing Appeal Board (Appeal Board). Subsequently, the AEC, specifically referring to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28","3":"17"}},{"t":"law","label":"Pub. L. No. 104-208","url":"https://www.govinfo.gov/link/plaw/104/public/208","by":{"0":"20","2":"5"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(42)(A)","(a)(42)(B)","(a)(42)"],"stext":{"head":"§1101. Definitions","paras":[[0,"(a) As used in this chapter—"],[0,"(1) The term \"administrator\" means the official designated by the Secretary of State pursuant to section 1104(b) of this title."],[0,"(2) The term \"advocates\" includes, but is not limited to, advises, recommends, furthers by overt act, and admits belief in."],[0,"(3) The term \"alien\" means any person not a citizen or national of the United States."],[0,"(4) The term \"application for admission\" has reference to the application for admission into the United States and not to the application for the issuance of an immigrant or nonimmigrant visa."],[0,"(5) The term \"Attorney General\" means the Attorney General of the United States."],[0,"(6) The term \"border crossing identification card\" means a document of identity bearing that designation issued to an alien who is lawfully admitted for permanent residence, or to an alien who is a resident in foreign contiguous territory, by a consular officer or an immigration officer for the purpose of crossing over the borders between the United States and foreign contiguous territory in accordance with such conditions for its issuance and use as may be prescribed by regulations. Such regulations shall provide that (A) each such document include a biometric identifier (such as the fingerprint or handprint of the alien) that is machine readable and (B) an alien presenting a border crossing identification card is not permitted to cross over the border into the United States unless the biometric identifier contained on the card matches the appropriate biometric characteristic of the alien."],[0,"(7) The term \"clerk of court\" means a clerk of a naturalization court."],[0,"(8) The terms \"Commissioner\" and \"Deputy Commissioner\" mean the Commissioner of Immigration and Naturalization and a Deputy Commissioner of Immigration and Naturalization, respectively."],[0,"(9) The term \"consular officer\" means any consular, diplomatic, or other officer or employee of the United States designated under regulations prescribed under authority contained in this chapter, for the purpose of issuing immigrant or nonimmigrant visas or, when used in subchapter III, for the purpose of adjudicating nationality."],[0,"(10) The term \"crewman\" means a person serving in any capacity on board a vessel or aircraft."],[0,"(11) The term \"diplomatic visa\" means a nonimmigrant visa bearing that title and issued to a nonimmigrant in accordance with such regulations as the Secretary of State may prescribe."],[0,"(12) The term \"doctrine\" includes, but is not limited to, policies, practices, purposes, aims, or procedures."],[0,"(13)(A) The terms \"admission\" and \"admitted\" mean, with respect to an alien, the lawful entry of the alien into the United States after inspection and authorization by an immigration officer."],[0,"(B) An alien who is paroled under section 1182(d)(5) of this title or permitted to land temporarily as an alien crewman shall not be considered to have been admitted."],[0,"(C) An alien lawfully admitted for permanent residence in the United States shall not be regarded as seeking an admission into the United States for purposes of the immigration laws unless the alien—"],[1,"(i) has abandoned or relinquished that status,"],[1,"(ii) has been absent from the United States for a continuous period in excess of 180 days,"],[1,"(iii) has engaged in illegal activity after having departed the United States,"],[1,"(iv) has departed from the United States while under legal process seeking removal of the alien from the United States, including removal proceedings under this chapter and extradition proceedings,"],[1,"(v) has committed an offense identified in section 1182(a)(2) of this title, unless since such offense the alien has been granted relief under section 1182(h) or 1229b(a) of this title, or"],[1,"(vi) is attempting to enter at a time or place other than as designated by immigration officers or has not been admitted to the United States after inspection and authorization by an immigration officer."],[0,"(14) The term \"foreign state\" includes outlying possessions of a foreign state, but self-governing dominions or territories under mandate or trusteeship shall be regarded as separate foreign states."],[0,"(15) The term \"immigrant\" means every alien except an alien who is within one of the following classes of nonimmigrant aliens—"],[1,"(A)(i) an ambassador, public minister, or career diplomatic or consular officer who has been accredited by a foreign government, recognized de jure by the United States and who is accepted by the President or by the Secretary of State, and the members of the alien's immediate family;"],[1,"(ii) upon a basis of reciprocity, other officials and employees who have been accredited by a foreign government recognized de jure by the United States, who are accepted by the Secretary of State, and the members of their immediate families; and"],[1,"(iii) upon a basis of reciprocity, attendants, servants, personal employees, and members of their immediate families, of the officials and employees who have a nonimmigrant status under (i) and (ii) above;"],[1,"(B) an alien (other than one coming for the purpose of study or of performing skilled or unskilled labor or as a representative of foreign press, radio, film, or other foreign information media coming to engage in such vocation) having a residence in a foreign country which he has no intention of abandoning and who is visiting the United States temporarily for business or temporarily for pleasure;"],[1,"(C)(i) an alien in immediate and continuous transit through the United States, for a period not to exceed 29 days;"],[1,"(ii) an alien who qualifies as a person entitled to pass in transit to and from the United Nations Headquarters District (as defined in section 4309a(e) of title 22) and foreign countries, under the provisions of paragraphs (3), (4), and (5) of section 11 of the Agreement regarding the Headquarters of the United Nations, done at Lake Success June 26, 1947 (61 Stat. 758); or"],[1,"(iii) an alien passing in transit through the United States to board a vessel on which the alien will perform, or to disembark from a vessel on which the alien performed, ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, for a period not to exceed 180 days;"],[1,"(D)(i) an alien crewman serving in good faith as such in a capacity required for normal operation and service on board a vessel, as defined in section 1288(a) of this title (other than a fishing vessel having its home port or an operating base in the United States), or aircraft, who intends to land temporarily and solely in pursuit of his calling as a crewman and to depart from the United States with the vessel or aircraft on which he arrived or some other vessel or aircraft;"],[1,"(ii) an alien crewman serving in good faith as such in any capacity required for normal operations and service aboard a fishing vessel having its home port or an operating base in the United States who intends to land temporarily in Guam or the Commonwealth of the Northern Mariana Islands and solely in pursuit of his calling as a crewman and to depart from Guam or the Commonwealth of the Northern Mariana Islands with the vessel on which he arrived; or"],[1,"(iii) an alien crewman performing ship-to-ship liquid cargo transfer operations to or from another vessel engaged in foreign trade, who intends to land temporarily solely in pursuit of the alien's responsibilities as a crewman and to depart from the United States on the vessel on which the alien arrived or on another vessel or aircraft, for a period not to exceed 180 days;"],[1,"(E) an alien entitled to enter the United States under and in pursuance of the provisions of a treaty of commerce and navigation between the United States and the foreign state of which the alien is a national (or, in the case of an alien who acquired the relevant nationality through a financial investment and who has not previously been granted status under this subparagraph, the foreign state of which the alien is a national and in which the alien has been domiciled for a continuous period of not less than 3 years at any point before applying for a nonimmigrant visa under this subparagraph), and the spouse and children of any such alien if accompanying or following to join such alien; (i) solely to carry on substantial trade, including trade in services or trade in technology, principally between the United States and the foreign state of which the alien is a national; (ii) solely to develop and direct the operations of an enterprise in which the alien has invested, or of an enterprise in which the alien is actively in the process of investing, a substantial amount of capital; or (iii) solely to perform services in a specialty occupation in the United States if the alien is a national of the Commonwealth of Australia and with respect to whom the Secretary of Labor determines and certifies to the Secretary of Homeland Security and the Secretary of State that the intending employer has filed with the Secretary of Labor an attestation under section 1182(t)(1) of this title;"],[1,"(F)(i) an alien having a residence in a foreign country which he has no intention of abandoning, who is a bona fide student qualified to pursue a full course of study and who seeks to enter the United States temporarily and solely for the purpose of pursuing such a course of study consistent with section 1184(l) 1 of this title at an established college, university, seminary, conservatory, academic high school, elementary school, or other academic institution or in an accredited language training program in the United States, particularly designated by him and approved by the Attorney General after consultation with the Secretary of Education, which institution or place of study shall have agreed to report to the Attorney General the termination of attendance of each nonimmigrant student, and if any such institution of learning or place of study fails to make reports promptly the approval shall be withdrawn, (ii) the alien spouse and minor children of any alien described in clause (i) if accompanying or following to join such an alien, and (iii) an alien who is a national of Canada or Mexico, who maintains actual residence and place of abode in the country of nationality, who is described in clause (i) except that the alien's qualifications for and actual course of study may be full or part-time, and who commutes to the United States institution or place of study from Canada or Mexico;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1101. Definitions","tname":"Aliens and Nationality","by":{"0":"3, 3, 3","1":"4","3":"1"}},{"t":"usc","label":"8 U.S.C. § 1158","url":"https://www.law.cornell.edu/uscode/text/8/1158","subs":["(a)","(b)(1)(A)","(b)(1)(B)(ii)","(b)(1)(B)(iii)","(b)(1)(B)","(b)(2)(A)(i)","(b)(2)(A)(ii)"],"stext":{"head":"§1158. Asylum","paras":[[0,"(a) Authority to apply for asylum"],[0,"(1) In general"],[1,"Any alien who is physically present in the United States or who arrives in the United States (whether or not at a designated port of arrival and including an alien who is brought to the United States after having been interdicted in international or United States waters), irrespective of such alien's status, may apply for asylum in accordance with this section or, where applicable, section 1225(b) of this title."],[0,"(2) Exceptions"],[0,"(A) Safe third country"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that the alien may be removed, pursuant to a bilateral or multilateral agreement, to a country (other than the country of the alien's nationality or, in the case of an alien having no nationality, the country of the alien's last habitual residence) in which the alien's life or freedom would not be threatened on account of race, religion, nationality, membership in a particular social group, or political opinion, and where the alien would have access to a full and fair procedure for determining a claim to asylum or equivalent temporary protection, unless the Attorney General finds that it is in the public interest for the alien to receive asylum in the United States."],[0,"(B) Time limit"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien unless the alien demonstrates by clear and convincing evidence that the application has been filed within 1 year after the date of the alien's arrival in the United States."],[0,"(C) Previous asylum applications"],[2,"Subject to subparagraph (D), paragraph (1) shall not apply to an alien if the alien has previously applied for asylum and had such application denied."],[0,"(D) Changed circumstances"],[2,"An application for asylum of an alien may be considered, notwithstanding subparagraphs (B) and (C), if the alien demonstrates to the satisfaction of the Attorney General either the existence of changed circumstances which materially affect the applicant's eligibility for asylum or extraordinary circumstances relating to the delay in filing an application within the period specified in subparagraph (B)."],[0,"(E) Applicability"],[2,"Subparagraphs (A) and (B) shall not apply to an unaccompanied alien child (as defined in section 279(g) of title 6)."],[0,"(3) Limitation on judicial review"],[1,"No court shall have jurisdiction to review any determination of the Attorney General under paragraph (2)."],[0,"(b) Conditions for granting asylum"],[0,"(1) In general"],[0,"(A) Eligibility"],[2,"The Secretary of Homeland Security or the Attorney General may grant asylum to an alien who has applied for asylum in accordance with the requirements and procedures established by the Secretary of Homeland Security or the Attorney General under this section if the Secretary of Homeland Security or the Attorney General determines that such alien is a refugee within the meaning of section 1101(a)(42)(A) of this title."],[0,"(B) Burden of proof"],[0,"(i) In general"],[3,"The burden of proof is on the applicant to establish that the applicant is a refugee, within the meaning of section 1101(a)(42)(A) of this title. To establish that the applicant is a refugee within the meaning of such section, the applicant must establish that race, religion, nationality, membership in a particular social group, or political opinion was or will be at least one central reason for persecuting the applicant."],[0,"(ii) Sustaining burden"],[3,"The testimony of the applicant may be sufficient to sustain the applicant's burden without corroboration, but only if the applicant satisfies the trier of fact that the applicant's testimony is credible, is persuasive, and refers to specific facts sufficient to demonstrate that the applicant is a refugee. In determining whether the applicant has met the applicant's burden, the trier of fact may weigh the credible testimony along with other evidence of record. Where the trier of fact determines that the applicant should provide evidence that corroborates otherwise credible testimony, such evidence must be provided unless the applicant does not have the evidence and cannot reasonably obtain the evidence."],[0,"(iii) Credibility determination"],[3,"Considering the totality of the circumstances, and all relevant factors, a trier of fact may base a credibility determination on the demeanor, candor, or responsiveness of the applicant or witness, the inherent plausibility of the applicant's or witness's account, the consistency between the applicant's or witness's written and oral statements (whenever made and whether or not under oath, and considering the circumstances under which the statements were made), the internal consistency of each such statement, the consistency of such statements with other evidence of record (including the reports of the Department of State on country conditions), and any inaccuracies or falsehoods in such statements, without regard to whether an inconsistency, inaccuracy, or falsehood goes to the heart of the applicant's claim, or any other relevant factor. There is no presumption of credibility, however, if no adverse credibility determination is explicitly made, the applicant or witness shall have a rebuttable presumption of credibility on appeal."],[0,"(2) Exceptions"],[0,"(A) In general"],[2,"Paragraph (1) shall not apply to an alien if the Attorney General determines that—"],[3,"(i) the alien ordered, incited, assisted, or otherwise participated in the persecution of any person on account of race, religion, nationality, membership in a particular social group, or political opinion;"],[3,"(ii) the alien, having been convicted by a final judgment of a particularly serious crime, constitutes a danger to the community of the United States;"],[3,"(iii) there are serious reasons for believing that the alien has committed a serious nonpolitical crime outside the United States prior to the arrival of the alien in the United States;"],[3,"(iv) there are reasonable grounds for regarding the alien as a danger to the security of the United States;"],[3,"(v) the alien is described in subclause (I), (II), (III), (IV), or (VI) of section 1182(a)(3)(B)(i) of this title or section 1227(a)(4)(B) of this title (relating to terrorist activity), unless, in the case only of an alien described in subclause (IV) of section 1182(a)(3)(B)(i) of this title, the Attorney General determines, in the Attorney General's discretion, that there are not reasonable grounds for regarding the alien as a danger to the security of the United States; or"],[3,"(vi) the alien was firmly resettled in another country prior to arriving in the United States."],[0,"(B) Special rules"],[0,"(i) Conviction of aggravated felony"],[3,"For purposes of clause (ii) of subparagraph (A), an alien who has been convicted of an aggravated felony shall be considered to have been convicted of a particularly serious crime."],[0,"(ii) Offenses"],[3,"The Attorney General may designate by regulation offenses that will be considered to be a crime described in clause (ii) or (iii) of subparagraph (A)."],[0,"(C) Additional limitations"],[2,"The Attorney General may by regulation establish additional limitations and conditions, consistent with this section, under which an alien shall be ineligible for asylum under paragraph (1)."],[0,"(D) No judicial review"],[2,"There shall be no judicial review of a determination of the Attorney General under subparagraph (A)(v)."],[0,"(3) Treatment of spouse and children"],[0,"(A) In general"],[2,"A spouse or child (as defined in section 1101(b)(1)(A), (B), (C), (D), or (E) of this title) of an alien who is granted asylum under this subsection may, if not otherwise eligible for asylum under this section, be granted the same status as the alien if accompanying, or following to join, such alien."],[0,"(B) Continued classification of certain aliens as children"],[2,"An unmarried alien who seeks to accompany, or follow to join, a parent granted asylum under this subsection, and who was under 21 years of age on the date on which such parent applied for asylum under this section, shall continue to be classified as a child for purposes of this paragraph and section 1159(b)(3) of this title, if the alien attained 21 years of age after such application was filed but while it was pending."],[0,"(C) Initial jurisdiction"],[2,"An asylum officer (as defined in section 1225(b)(1)(E) of this title) shall have initial jurisdiction over any asylum application filed by an unaccompanied alien child (as defined in section 279(g) of title 6), regardless of whether filed in accordance with this section or section 1225(b) of this title."],[0,"(c) Asylum status"],[0,"(1) In general"],[1,"In the case of an alien granted asylum under subsection (b), the Attorney General—"],[2,"(A) shall not remove or return the alien to the alien's country of nationality or, in the case of a person having no nationality, the country of the alien's last habitual residence;"],[2,"(B) shall authorize the alien to engage in employment in the United States and provide the alien with appropriate endorsement of that authorization; and"],[2,"(C) may allow the alien to travel abroad with the prior consent of the Attorney General."],[0,"(2) Termination of asylum"],[1,"Asylum granted under subsection (b) does not convey a right to remain permanently in the United States, and may be terminated if the Attorney General determines that—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1158?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1158. Asylum","tname":"Aliens and Nationality","by":{"0":"15, 15, 15, 15","1":"4, 5, 4, 4","3":"21, 5, 6, 14, 5, 3, 15, 16, 17"}},{"t":"usc","label":"8 U.S.C. § 1182","url":"https://www.law.cornell.edu/uscode/text/8/1182","subs":["(a)(2)(A)(i)(II)"],"by":{"0":"15"}},{"t":"usc","label":"8 U.S.C. § 1229a","url":"https://www.law.cornell.edu/uscode/text/8/1229a","subs":["(a)(1)","(c)(4)","(c)(4)(A)","(c)(4)(B)","(c)(4)(C)","(c)(5)","(c)(6)","(c)(7)"],"stext":{"head":"§1229a. Removal proceedings","paras":[[0,"(a) Proceeding"],[0,"(1) In general"],[1,"An immigration judge shall conduct proceedings for deciding the inadmissibility or deportability of an alien."],[0,"(2) Charges"],[1,"An alien placed in proceedings under this section may be charged with any applicable ground of inadmissibility under section 1182(a) of this title or any applicable ground of deportability under section 1227(a) of this title."],[0,"(3) Exclusive procedures"],[1,"Unless otherwise specified in this chapter, a proceeding under this section shall be the sole and exclusive procedure for determining whether an alien may be admitted to the United States or, if the alien has been so admitted, removed from the United States. Nothing in this section shall affect proceedings conducted pursuant to section 1228 of this title."],[0,"(b) Conduct of proceeding"],[0,"(1) Authority of immigration judge"],[1,"The immigration judge shall administer oaths, receive evidence, and interrogate, examine, and cross-examine the alien and any witnesses. The immigration judge may issue subpoenas for the attendance of witnesses and presentation of evidence. The immigration judge shall have authority (under regulations prescribed by the Attorney General) to sanction by civil money penalty any action (or inaction) in contempt of the judge's proper exercise of authority under this chapter."],[0,"(2) Form of proceeding"],[0,"(A) In general"],[2,"The proceeding may take place—"],[3,"(i) in person,"],[3,"(ii) where agreed to by the parties, in the absence of the alien,"],[3,"(iii) through video conference, or"],[3,"(iv) subject to subparagraph (B), through telephone conference."],[0,"(B) Consent required in certain cases"],[2,"An evidentiary hearing on the merits may only be conducted through a telephone conference with the consent of the alien involved after the alien has been advised of the right to proceed in person or through video conference."],[0,"(3) Presence of alien"],[1,"If it is impracticable by reason of an alien's mental incompetency for the alien to be present at the proceeding, the Attorney General shall prescribe safeguards to protect the rights and privileges of the alien."],[0,"(4) Alien's rights in proceeding"],[1,"In proceedings under this section, under regulations of the Attorney General—"],[2,"(A) the alien shall have the privilege of being represented, at no expense to the Government, by counsel of the alien's choosing who is authorized to practice in such proceedings,"],[2,"(B) the alien shall have a reasonable opportunity to examine the evidence against the alien, to present evidence on the alien's own behalf, and to cross-examine witnesses presented by the Government but these rights shall not entitle the alien to examine such national security information as the Government may proffer in opposition to the alien's admission to the United States or to an application by the alien for discretionary relief under this chapter, and"],[2,"(C) a complete record shall be kept of all testimony and evidence produced at the proceeding."],[0,"(5) Consequences of failure to appear"],[0,"(A) In general"],[2,"Any alien who, after written notice required under paragraph (1) or (2) of section 1229(a) of this title has been provided to the alien or the alien's counsel of record, does not attend a proceeding under this section, shall be ordered removed in absentia if the Service establishes by clear, unequivocal, and convincing evidence that the written notice was so provided and that the alien is removable (as defined in subsection (e)(2)). The written notice by the Attorney General shall be considered sufficient for purposes of this subparagraph if provided at the most recent address provided under section 1229(a)(1)(F) of this title."],[0,"(B) No notice if failure to provide address information"],[2,"No written notice shall be required under subparagraph (A) if the alien has failed to provide the address required under section 1229(a)(1)(F) of this title."],[0,"(C) Rescission of order"],[2,"Such an order may be rescinded only—"],[3,"(i) upon a motion to reopen filed within 180 days after the date of the order of removal if the alien demonstrates that the failure to appear was because of exceptional circumstances (as defined in subsection (e)(1)), or"],[3,"(ii) upon a motion to reopen filed at any time if the alien demonstrates that the alien did not receive notice in accordance with paragraph (1) or (2) of section 1229(a) of this title or the alien demonstrates that the alien was in Federal or State custody and the failure to appear was through no fault of the alien."],[2,"The filing of the motion to reopen described in clause (i) or (ii) shall stay the removal of the alien pending disposition of the motion by the immigration judge."],[0,"(D) Effect on judicial review"],[2,"Any petition for review under section 1252 of this title of an order entered in absentia under this paragraph shall (except in cases described in section 1252(b)(5) of this title) be confined to (i) the validity of the notice provided to the alien, (ii) the reasons for the alien's not attending the proceeding, and (iii) whether or not the alien is removable."],[0,"(E) Additional application to certain aliens in contiguous territory"],[2,"The preceding provisions of this paragraph shall apply to all aliens placed in proceedings under this section, including any alien who remains in a contiguous foreign territory pursuant to section 1225(b)(2)(C) of this title."],[0,"(6) Treatment of frivolous behavior"],[1,"The Attorney General shall, by regulation—"],[2,"(A) define in a proceeding before an immigration judge or before an appellate administrative body under this subchapter, frivolous behavior for which attorneys may be sanctioned,"],[2,"(B) specify the circumstances under which an administrative appeal of a decision or ruling will be considered frivolous and will be summarily dismissed, and"],[2,"(C) impose appropriate sanctions (which may include suspension and disbarment) in the case of frivolous behavior."],[1,"Nothing in this paragraph shall be construed as limiting the authority of the Attorney General to take actions with respect to inappropriate behavior."],[0,"(7) Limitation on discretionary relief for failure to appear"],[1,"Any alien against whom a final order of removal is entered in absentia under this subsection and who, at the time of the notice described in paragraph (1) or (2) of section 1229(a) of this title, was provided oral notice, either in the alien's native language or in another language the alien understands, of the time and place of the proceedings and of the consequences under this paragraph of failing, other than because of exceptional circumstances (as defined in subsection (e)(1)) to attend a proceeding under this section, shall not be eligible for relief under section 1229b, 1229c, 1255, 1258, or 1259 of this title for a period of 10 years after the date of the entry of the final order of removal."],[0,"(c) Decision and burden of proof"],[0,"(1) Decision"],[0,"(A) In general"],[2,"At the conclusion of the proceeding the immigration judge shall decide whether an alien is removable from the United States. The determination of the immigration judge shall be based only on the evidence produced at the hearing."],[0,"(B) Certain medical decisions"],[2,"If a medical officer or civil surgeon or board of medical officers has certified under section 1222(b) of this title that an alien has a disease, illness, or addiction which would make the alien inadmissible under paragraph (1) of section 1182(a) of this title, the decision of the immigration judge shall be based solely upon such certification."],[0,"(2) Burden on alien"],[1,"In the proceeding the alien has the burden of establishing—"],[2,"(A) if the alien is an applicant for admission, that the alien is clearly and beyond doubt entitled to be admitted and is not inadmissible under section 1182 of this title; or"],[2,"(B) by clear and convincing evidence, that the alien is lawfully present in the United States pursuant to a prior admission."],[1,"In meeting the burden of proof under subparagraph (B), the alien shall have access to the alien's visa or other entry document, if any, and any other records and documents, not considered by the Attorney General to be confidential, pertaining to the alien's admission or presence in the United States."],[0,"(3) Burden on service in cases of deportable aliens"],[0,"(A) In general"],[2,"In the proceeding the Service has the burden of establishing by clear and convincing evidence that, in the case of an alien who has been admitted to the United States, the alien is deportable. No decision on deportability shall be valid unless it is based upon reasonable, substantial, and probative evidence."],[0,"(B) Proof of convictions"],[2,"In any proceeding under this chapter, any of the following documents or records (or a certified copy of such an official document or record) shall constitute proof of a criminal conviction:"],[3,"(i) An official record of judgment and conviction."],[3,"(ii) An official record of plea, verdict, and sentence."],[3,"(iii) A docket entry from court records that indicates the existence of the conviction."],[3,"(iv) Official minutes of a court proceeding or a transcript of a court hearing in which the court takes notice of the existence of the conviction."],[3,"(v) An abstract of a record of conviction prepared by the court in which the conviction was entered, or by a State official associated with the State's repository of criminal justice records, that indicates the charge or section of law violated, the disposition of the case, the existence and date of conviction, and the sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1229a?type=usc&year=mostrecent&link-type=html"},"head":"§1229a. Removal proceedings","tname":"Aliens and Nationality","by":{"0":"3, 29, 3, 29, 3, 29, 3, 29, 3, 29, 3, 29","1":"32, 5, 6, passim, passim, 32, 32, 32","3":"5"}},{"t":"usc","label":"8 U.S.C. § 1231","url":"https://www.law.cornell.edu/uscode/text/8/1231","subs":["(b)(3)","(b)(3)(A)","(b)(3)(B)(ii)","(b)(3)(C)","(b)(3)(B)(i)"],"stext":{"head":"§1231. Detention and removal of aliens ordered removed","paras":[[0,"(a) Detention, release, and removal of aliens ordered removed"],[0,"(1) Removal period"],[0,"(A) In general"],[2,"Except as otherwise provided in this section, when an alien is ordered removed, the Attorney General shall remove the alien from the United States within a period of 90 days (in this section referred to as the \"removal period\")."],[0,"(B) Beginning of period"],[2,"The removal period begins on the latest of the following:"],[3,"(i) The date the order of removal becomes administratively final."],[3,"(ii) If the removal order is judicially reviewed and if a court orders a stay of the removal of the alien, the date of the court's final order."],[3,"(iii) If the alien is detained or confined (except under an immigration process), the date the alien is released from detention or confinement."],[0,"(C) Suspension of period"],[2,"The removal period shall be extended beyond a period of 90 days and the alien may remain in detention during such extended period if the alien fails or refuses to make timely application in good faith for travel or other documents necessary to the alien's departure or conspires or acts to prevent the alien's removal subject to an order of removal."],[0,"(2) Detention"],[1,"During the removal period, the Attorney General shall detain the alien. Under no circumstance during the removal period shall the Attorney General release an alien who has been found inadmissible under section 1182(a)(2) or 1182(a)(3)(B) of this title or deportable under section 1227(a)(2) or 1227(a)(4)(B) of this title."],[0,"(3) Supervision after 90-day period"],[1,"If the alien does not leave or is not removed within the removal period, the alien, pending removal, shall be subject to supervision under regulations prescribed by the Attorney General. The regulations shall include provisions requiring the alien—"],[2,"(A) to appear before an immigration officer periodically for identification;"],[2,"(B) to submit, if necessary, to a medical and psychiatric examination at the expense of the United States Government;"],[2,"(C) to give information under oath about the alien's nationality, circumstances, habits, associations, and activities, and other information the Attorney General considers appropriate; and"],[2,"(D) to obey reasonable written restrictions on the alien's conduct or activities that the Attorney General prescribes for the alien."],[0,"(4) Aliens imprisoned, arrested, or on parole, supervised release, or probation"],[0,"(A) In general"],[2,"Except as provided in section 259(a) 1 of title 42 and paragraph (2),2 the Attorney General may not remove an alien who is sentenced to imprisonment until the alien is released from imprisonment. Parole, supervised release, probation, or possibility of arrest or further imprisonment is not a reason to defer removal."],[0,"(B) Exception for removal of nonviolent offenders prior to completion of sentence of imprisonment"],[2,"The Attorney General is authorized to remove an alien in accordance with applicable procedures under this chapter before the alien has completed a sentence of imprisonment—"],[3,"(i) in the case of an alien in the custody of the Attorney General, if the Attorney General determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense related to smuggling or harboring of aliens or an offense described in section 1101(a)(43)(B), (C), (E), (I), or (L) of this title 3 and (II) the removal of the alien is appropriate and in the best interest of the United States; or"],[3,"(ii) in the case of an alien in the custody of a State (or a political subdivision of a State), if the chief State official exercising authority with respect to the incarceration of the alien determines that (I) the alien is confined pursuant to a final conviction for a nonviolent offense (other than an offense described in section 1101(a)(43)(C) or (E) of this title), (II) the removal is appropriate and in the best interest of the State, and (III) submits a written request to the Attorney General that such alien be so removed."],[0,"(C) Notice"],[2,"Any alien removed pursuant to this paragraph shall be notified of the penalties under the laws of the United States relating to the reentry of deported aliens, particularly the expanded penalties for aliens removed under subparagraph (B)."],[0,"(D) No private right"],[2,"No cause or claim may be asserted under this paragraph against any official of the United States or of any State to compel the release, removal, or consideration for release or removal of any alien."],[0,"(5) Reinstatement of removal orders against aliens illegally reentering"],[1,"If the Attorney General finds that an alien has reentered the United States illegally after having been removed or having departed voluntarily, under an order of removal, the prior order of removal is reinstated from its original date and is not subject to being reopened or reviewed, the alien is not eligible and may not apply for any relief under this chapter, and the alien shall be removed under the prior order at any time after the reentry."],[0,"(6) Inadmissible or criminal aliens"],[1,"An alien ordered removed who is inadmissible under section 1182 of this title, removable under section 1227(a)(1)(C), 1227(a)(2), or 1227(a)(4) of this title or who has been determined by the Attorney General to be a risk to the community or unlikely to comply with the order of removal, may be detained beyond the removal period and, if released, shall be subject to the terms of supervision in paragraph (3)."],[0,"(7) Employment authorization"],[1,"No alien ordered removed shall be eligible to receive authorization to be employed in the United States unless the Attorney General makes a specific finding that—"],[2,"(A) the alien cannot be removed due to the refusal of all countries designated by the alien or under this section to receive the alien, or"],[2,"(B) the removal of the alien is otherwise impracticable or contrary to the public interest."],[0,"(b) Countries to which aliens may be removed"],[0,"(1) Aliens arriving at the United States"],[1,"Subject to paragraph (3)—"],[0,"(A) In general"],[2,"Except as provided by subparagraphs (B) and (C), an alien who arrives at the United States and with respect to whom proceedings under section 1229a of this title were initiated at the time of such alien's arrival shall be removed to the country in which the alien boarded the vessel or aircraft on which the alien arrived in the United States."],[0,"(B) Travel from contiguous territory"],[2,"If the alien boarded the vessel or aircraft on which the alien arrived in the United States in a foreign territory contiguous to the United States, an island adjacent to the United States, or an island adjacent to a foreign territory contiguous to the United States, and the alien is not a native, citizen, subject, or national of, or does not reside in, the territory or island, removal shall be to the country in which the alien boarded the vessel that transported the alien to the territory or island."],[0,"(C) Alternative countries"],[2,"If the government of the country designated in subparagraph (A) or (B) is unwilling to accept the alien into that country's territory, removal shall be to any of the following countries, as directed by the Attorney General:"],[3,"(i) The country of which the alien is a citizen, subject, or national."],[3,"(ii) The country in which the alien was born."],[3,"(iii) The country in which the alien has a residence."],[3,"(iv) A country with a government that will accept the alien into the country's territory if removal to each country described in a previous clause of this subparagraph is impracticable, inadvisable, or impossible."],[0,"(2) Other aliens"],[1,"Subject to paragraph (3)—"],[0,"(A) Selection of country by alien"],[2,"Except as otherwise provided in this paragraph—"],[3,"(i) any alien not described in paragraph (1) who has been ordered removed may designate one country to which the alien wants to be removed, and"],[3,"(ii) the Attorney General shall remove the alien to the country the alien so designates."],[0,"(B) Limitation on designation"],[2,"An alien may designate under subparagraph (A)(i) a foreign territory contiguous to the United States, an adjacent island, or an island adjacent to a foreign territory contiguous to the United States as the place to which the alien is to be removed only if the alien is a native, citizen, subject, or national of, or has resided in, that designated territory or island."],[0,"(C) Disregarding designation"],[2,"The Attorney General may disregard a designation under subparagraph (A)(i) if—"],[3,"(i) the alien fails to designate a country promptly;"],[3,"(ii) the government of the country does not inform the Attorney General finally, within 30 days after the date the Attorney General first inquires, whether the government will accept the alien into the country;"],[3,"(iii) the government of the country is not willing to accept the alien into the country; or"],[3,"(iv) the Attorney General decides that removing the alien to the country is prejudicial to the United States."],[0,"(D) Alternative country"],[2,"If an alien is not removed to a country designated under subparagraph (A)(i), the Attorney General shall remove the alien to a country of which the alien is a subject, national, or citizen unless the government of the country—"],[3,"(i) does not inform the Attorney General or the alien finally, within 30 days after the date the Attorney General first inquires or within another period of time the Attorney General decides is reasonable, whether the government will accept the alien into the country; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1231?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1231. Detention and removal of aliens ordered removed","tname":"Aliens and Nationality","by":{"0":"3, 29, 3, 29, 3, 29, 3, 29","1":"10, 4, 4, 4, 5, 26","3":"5"}},{"t":"usc","label":"8 U.S.C. § 1252","url":"https://www.law.cornell.edu/uscode/text/8/1252","subs":["(a)(1)","(b)(2)","(b)(4)","(b)(4)(B)","(b)"],"stext":{"head":"§1252. Judicial review of orders of removal","paras":[[0,"(a) Applicable provisions"],[0,"(1) General orders of removal"],[1,"Judicial review of a final order of removal (other than an order of removal without a hearing pursuant to section 1225(b)(1) of this title) is governed only by chapter 158 of title 28, except as provided in subsection (b) and except that the court may not order the taking of additional evidence under section 2347(c) of such title."],[0,"(2) Matters not subject to judicial review"],[0,"(A) Review relating to section 1225(b)(1)"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, no court shall have jurisdiction to review—"],[3,"(i) except as provided in subsection (e), any individual determination or to entertain any other cause or claim arising from or relating to the implementation or operation of an order of removal pursuant to section 1225(b)(1) of this title,"],[3,"(ii) except as provided in subsection (e), a decision by the Attorney General to invoke the provisions of such section,"],[3,"(iii) the application of such section to individual aliens, including the determination made under section 1225(b)(1)(B) of this title, or"],[3,"(iv) except as provided in subsection (e), procedures and policies adopted by the Attorney General to implement the provisions of section 1225(b)(1) of this title."],[0,"(B) Denials of discretionary relief"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), and regardless of whether the judgment, decision, or action is made in removal proceedings, no court shall have jurisdiction to review—"],[3,"(i) any judgment regarding the granting of relief under section 1182(h), 1182(i), 1229b, 1229c, or 1255 of this title, or"],[3,"(ii) any other decision or action of the Attorney General or the Secretary of Homeland Security the authority for which is specified under this subchapter to be in the discretion of the Attorney General or the Secretary of Homeland Security, other than the granting of relief under section 1158(a) of this title."],[0,"(C) Orders against criminal aliens"],[2,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, and except as provided in subparagraph (D), no court shall have jurisdiction to review any final order of removal against an alien who is removable by reason of having committed a criminal offense covered in section 1182(a)(2) or 1227(a)(2)(A)(iii), (B), (C), or (D) of this title, or any offense covered by section 1227(a)(2)(A)(ii) of this title for which both predicate offenses are, without regard to their date of commission, otherwise covered by section 1227(a)(2)(A)(i) of this title."],[0,"(D) Judicial review of certain legal claims"],[2,"Nothing in subparagraph (B) or (C), or in any other provision of this chapter (other than this section) which limits or eliminates judicial review, shall be construed as precluding review of constitutional claims or questions of law raised upon a petition for review filed with an appropriate court of appeals in accordance with this section."],[0,"(3) Treatment of certain decisions"],[1,"No alien shall have a right to appeal from a decision of an immigration judge which is based solely on a certification described in section 1229a(c)(1)(B) of this title."],[0,"(4) Claims under the United Nations Convention"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of any cause or claim under the United Nations Convention Against Torture and Other Forms of Cruel, Inhuman, or Degrading Treatment or Punishment, except as provided in subsection (e)."],[0,"(5) Exclusive means of review"],[1,"Notwithstanding any other provision of law (statutory or nonstatutory), including section 2241 of title 28, or any other habeas corpus provision, and sections 1361 and 1651 of such title, a petition for review filed with an appropriate court of appeals in accordance with this section shall be the sole and exclusive means for judicial review of an order of removal entered or issued under any provision of this chapter, except as provided in subsection (e). For purposes of this chapter, in every provision that limits or eliminates judicial review or jurisdiction to review, the terms \"judicial review\" and \"jurisdiction to review\" include habeas corpus review pursuant to section 2241 of title 28, or any other habeas corpus provision, sections 1361 and 1651 of such title, and review pursuant to any other provision of law (statutory or nonstatutory)."],[0,"(b) Requirements for review of orders of removal"],[0,"With respect to review of an order of removal under subsection (a)(1), the following requirements apply:"],[0,"(1) Deadline"],[1,"The petition for review must be filed not later than 30 days after the date of the final order of removal."],[0,"(2) Venue and forms"],[1,"The petition for review shall be filed with the court of appeals for the judicial circuit in which the immigration judge completed the proceedings. The record and briefs do not have to be printed. The court of appeals shall review the proceeding on a typewritten record and on typewritten briefs."],[0,"(3) Service"],[0,"(A) In general"],[2,"The respondent is the Attorney General. The petition shall be served on the Attorney General and on the officer or employee of the Service in charge of the Service district in which the final order of removal under section 1229a of this title was entered."],[0,"(B) Stay of order"],[2,"Service of the petition on the officer or employee does not stay the removal of an alien pending the court's decision on the petition, unless the court orders otherwise."],[0,"(C) Alien's brief"],[2,"The alien shall serve and file a brief in connection with a petition for judicial review not later than 40 days after the date on which the administrative record is available, and may serve and file a reply brief not later than 14 days after service of the brief of the Attorney General, and the court may not extend these deadlines except upon motion for good cause shown. If an alien fails to file a brief within the time provided in this paragraph, the court shall dismiss the appeal unless a manifest injustice would result."],[0,"(4) Scope and standard for review"],[1,"Except as provided in paragraph (5)(B)—"],[2,"(A) the court of appeals shall decide the petition only on the administrative record on which the order of removal is based,"],[2,"(B) the administrative findings of fact are conclusive unless any reasonable adjudicator would be compelled to conclude to the contrary,"],[2,"(C) a decision that an alien is not eligible for admission to the United States is conclusive unless manifestly contrary to law, and"],[2,"(D) the Attorney General's discretionary judgment whether to grant relief under section 1158(a) of this title shall be conclusive unless manifestly contrary to the law and an abuse of discretion."],[1,"No court shall reverse a determination made by a trier of fact with respect to the availability of corroborating evidence, as described in section 1158(b)(1)(B), 1229a(c)(4)(B), or 1231(b)(3)(C) of this title, unless the court finds, pursuant to subsection (b)(4)(B), that a reasonable trier of fact is compelled to conclude that such corroborating evidence is unavailable."],[0,"(5) Treatment of nationality claims"],[0,"(A) Court determination if no issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds from the pleadings and affidavits that no genuine issue of material fact about the petitioner's nationality is presented, the court shall decide the nationality claim."],[0,"(B) Transfer if issue of fact"],[2,"If the petitioner claims to be a national of the United States and the court of appeals finds that a genuine issue of material fact about the petitioner's nationality is presented, the court shall transfer the proceeding to the district court of the United States for the judicial district in which the petitioner resides for a new hearing on the nationality claim and a decision on that claim as if an action had been brought in the district court under section 2201 of title 28."],[0,"(C) Limitation on determination"],[2,"The petitioner may have such nationality claim decided only as provided in this paragraph."],[0,"(6) Consolidation with review of motions to reopen or reconsider"],[1,"When a petitioner seeks review of an order under this section, any review sought of a motion to reopen or reconsider the order shall be consolidated with the review of the order."],[0,"(7) Challenge to validity of orders in certain criminal proceedings"],[0,"(A) In general"],[2,"If the validity of an order of removal has not been judicially decided, a defendant in a criminal proceeding charged with violating section 1253(a) of this title may challenge the validity of the order in the criminal proceeding only by filing a separate motion before trial. The district court, without a jury, shall decide the motion before trial."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/8/1252?type=usc&year=mostrecent&link-type=html"},"op":5,"ar":3,"head":"§1252. Judicial review of orders of removal","tname":"Aliens and Nationality","by":{"0":"3, 29, 3, 29, 3, 29, 3, 29","1":"32, 36, 7, 28, 34","3":"2, 10, 12, 16, 17"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","subs":["(2)(E)"],"stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"21"}},{"t":"usc","label":"28 U.S.C. § 2344","url":"https://www.law.cornell.edu/uscode/text/28/2344","by":{"0":"29"}},{"t":"case","label":"Aden v. Holder","cite":"589 F.3d 1040","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/589/1040/","by":{"1":"38, 39"}},{"t":"case","label":"Alpharma, Inc. v. Leavitt","cite":"460 F.3d 1","y":2006,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/460/1/","sum":"Upholding agency decision following remand because the agency “provide[d] a satisfactory explanation” for its initial decision.","sumSrc":"brief:1","by":{"1":"47"}},{"t":"case","label":"Am. Textile Mfrs. Inst., Inc. v. Donovan","cite":"452 U.S. 490","y":1981,"id":"1980/79-1429","sc":1,"sum":"The Court held that the language of the Occupational Safety and Health Act requires the Occupational Safety and Health Administration to engage in feasibility analysis but not a cost-benefit analysis.","sumSrc":"Oyez","by":{"1":"23, 40, 41","2":"4, 26, 28, 41"}},{"t":"case","label":"Anderson v. City of Bessemer City","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"sum":"The Court of Appeals misapprehended and misapplied the clearlyerroneous standard and accordingly erred in denying petitioner relief under Title VII.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26","2":"34"}},{"t":"case","label":"Antropova v. Holder","cite":"553 F. App’x 49","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/553/49/","by":{"1":"39"}},{"t":"case","label":"Arkansas v. Oklahoma","cite":"503 U.S. 91","y":1992,"id":"1991/90-1262","sc":1,"op":1,"sum":"The EPA's action was authorized by the Clean Water Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19, 28"}},{"t":"case","label":"Beth Israel Hosp. v. NLRB","cite":"437 U.S. 483","y":1978,"id":"1977/77-152","sc":1,"sum":"The Court held that, since 1974, the Act provided employees of nonprofit healthcare institutions with the right to self-organize and bargain collectively, including the right to communicate about the topic at the jobsite. However, an employer may curb that right by showing that special circumstances necessitate the prohibition of communication in order to maintain production or discipline.","sumSrc":"Oyez","by":{"1":"22, 40"}},{"t":"case","label":"Black v. Cutter Labs.","cite":"351 U.S. 292","y":1956,"id":"1955/92","sc":1,"op":1,"sum":"The decision involves only California's construction of a local contract under local law; no substantial federal question is presented; and the writ of certiorari is dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"case","label":"Bowen v. Am. Hosp. Ass’n","cite":"476 U.S. 610","y":1986,"id":"1985/84-1529","sc":1,"sum":"The judgment is affirmed. 794 F. 2d 676, affirmed. JUSTICE STEVENS, joined by JUSTICE MARSHALL, JUSTICE BLACKMUN, and JUSTICE POWELL, concluded that the regulations in question are not authorized by § 504.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 25"}},{"t":"case","label":"Burlington Truck Lines, Inc. v. United States","cite":"371 U.S. 156","y":1962,"id":"1962/27","sc":1,"sum":"The judgment is reversed and the case is remanded to the District Court with instructions to set aside the Commission's order and remand the case to the Commission for further proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Chevron U.S.A., Inc. v. Nat. Res. Def. Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"Consolidated Edison Co. v. NLRB","cite":"305 U.S. 197","y":1938,"id":"scdb/1938-001","sc":1,"sum":"1. The power of the Federal Government, and the provisions of the National Labor Relations Act, extend to the labor relations of public utilities engaged in supplying electrical energy, gas and steam, where the business and activities of the utilities are wholly within a State, and where the quantum of service rendered to customers for strictly intrastate uses is vast and greatly preponderant, but where, …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17"}},{"t":"case","label":"Clay v. United States","cite":"537 U.S. 522","y":2003,"id":"2002/01-1500","sc":1,"sum":"The Court held that, for the purpose of starting the clock on section 2255's one-year limitation period, a judgment of conviction becomes final when the time expires for filing a petition for certiorari contesting the appellate court's affirmation of the conviction. Under this rule, Clay's section 2255 motion was timely filed.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"De Leon-Barrios v. INS","cite":"116 F.3d 391","y":1997,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/116/391/","by":{"1":"27, 35"}},{"t":"case","label":"Dep’t of Homeland Sec. v. Regents of the Univ. of Cal.","cite":"140 S. Ct. 1891","y":2020,"id":"2019/18-587","sc":1,"sum":"The Court held that the Department of Homeland Security’s decision to rescind the Deferred Action for Childhood Arrivals program was arbitrary and capricious under the Administrative Procedure Act.","sumSrc":"Oyez","by":{"1":"18, 25, 47"}},{"t":"case","label":"Dickinson v. United States","cite":"346 U.S. 389","y":1953,"id":"scdb/1953-012","sc":1,"sum":"There was no basis in.fact for denying petitioner's claim to ministerial exemption under § 6 (g) of the Universal Military Training and Service Act, and his conviction for refusing to submit to his local board's induction order is reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Dickinson v. Zurko","cite":"527 U.S. 150","y":1999,"id":"1998/98-377","sc":1,"sum":"The Court held that the Court of Appeals for the Federal Circuit must use the framework set forth in the Administrative Procedure Act when reviewing PTO findings of fact.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"FCC v. Allentown Broad. Corp.","cite":"349 U.S. 358","y":1955,"id":"scdb/1954-089","sc":1,"sum":"1. The Federal Communications Commission, in considering two mutually exclusive applications for radio broadcasting stations in different communities, under § 307 (b) of the Communications Act, may properly decide in favor of one applicant over the other on the basis of community need without first finding that the applicants are approximately equal in their ability to serve their respective communities.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"FTC v. Indiana Fed’n of Dentists","cite":"476 U.S. 447","y":1986,"id":"1985/84-1809","sc":1,"sum":"Respondent organization of dentists in Indiana promulgated a policy requiring its members to withhold x rays from dental insurers in connection with evaluating patients' claims for benefits. The Federal Trade Commission (FTC) issued a cease-and-desist order, ruling that the policy constituted an unfair method of competition in violation of §5 of the Federal Trade Commission Act, since it amounted to a conspiratorial …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"FTC v. Standard Oil Co.","cite":"355 U.S. 396","y":1958,"id":"1957/24","sc":1,"sum":"The case turns on a factual issue, decided by the Court of Appeals upon a fair assessment of the record, and its judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"E.I. du Pont de Nemours & Co. v. Train","cite":"430 U.S. 112","y":1977,"id":"1976/75-978","sc":1,"sum":"The Court held that the Environmental Protection Agency could place categorical pollution limits on existing manufacturing plants while also placing absolute pollution limits on newly constructed manufacturing plants.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Gastelum-Quinones v. Kennedy","cite":"374 U.S. 469","y":1963,"id":"1962/39","sc":1,"sum":"On the record in this case, the Government did not sustain its burden of establishing that petitioner's association with the Communist Party was meaningful, as contemplated by § 241 (a) (6) (C), and the deportation order cannot stand. Rowoldt v. Perfetto, 355 U. S. 115.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Genuine Parts Co. v. EPA","cite":"890 F.3d 313","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/890/313/","by":{"1":"23"}},{"t":"case","label":"Golden State Bottling Co., Inc. v. NLRB","cite":"414 U.S. 168","y":1973,"id":"1973/72-702","sc":1,"sum":"Petitioner All American Beverages, Inc. (All American), purchased the soft drink bottling and distribution business of petitioner Golden State Bottling Co. (Golden State) after the National Labor Relations Board (NLRB) had ordered Golden State, \"its officers, agents, successors, and assigns\" to reinstate with backpay a driver-salesman whose discharge by Golden State was found to have been an unfair labor practice. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Gutierrez-Orozco v. Lynch","cite":"810 F.3d 1243","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/810/1243/","op":1,"by":{"1":"39"}},{"t":"case","label":"Haider v. Holder","cite":"595 F.3d 276","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/595/276/","by":{"1":"36","3":"18"}},{"t":"case","label":"Henderson ex rel. Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Jackson v. Virginia","cite":"443 U.S. 307","y":1979,"id":"1978/78-5283","sc":1,"sum":"Petitioner was convicted of first-degree murder after a bench trial in a Virginia court, and his motion and petition in the state courts to set aside the conviction on the ground that there was insufficient evidence of premeditation, a necessary element of first-degree murder, were denied. He then brought a habeas corpus proceeding in Federal District Court, which, applying the \"no evidence\" criterion of Thompson v. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"J.E. Riley Inv. Co. v. Comm’r","cite":"311 U.S. 55","y":1940,"id":"scdb/1940-018","sc":1,"sum":"that an amended return, filed after the expiration of the statutory period for filing the original return, including such extension of the period as the Commissioner was empowered to grant, was not a \"first return\" within the meaning of the section.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Judulang v. Holder","cite":"565 U.S. 42","y":2011,"id":"2011/10-694","sc":1,"ar":1,"sum":"The Court held that the policy used to determine whether a resident alien is able to ask for relief from deportation under a repealed portion of immigration laws is “arbitrary and capricious” under the Administrative Procedure Act, 5 U.S.C. § 706(2)(A).","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"Lin Yan v. Holder","cite":"559 F. App’x 658","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/559/658/","by":{"1":"27"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"1":"18, 24","3":"15"}},{"t":"case","label":"Mobil Oil Corp. v. Fed. Power Comm’n","cite":"417 U.S. 283","y":1974,"id":"1973/73-437","sc":1,"sum":"The Federal Power Commission (FPC) instituted a proceeding in 1961 to establish an area rate structure for interstate sales of natural gas produced in the Southern Louisiana area. After extensive hearings the FPC in 1968 issued an order establishing ceiling rates for gas sold by producers in the area and ordering refunds of rates in excess of the maximum that had been collected prior to the order. The Court of …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"40"}},{"t":"case","label":"Motor Vehicle Mfrs. Ass’n of U.S., Inc. v. State Farm Mut. Auto. Ins. Co.","cite":"463 U.S. 29","y":1983,"id":"1982/82-354","sc":1,"sum":"The Supreme Court held that the rescission of a standard should be reviewed based on whether the decision was arbitrary or capricious. Because the removal of a standard often entails the same level of policy changes as the promulgation of a law, it should be reviewed under the same tests.","sumSrc":"Oyez","by":{"1":"23, 25"}},{"t":"case","label":"NLRB v. Baptist Hosp., Inc.","cite":"442 U.S. 773","y":1979,"id":"1978/78-223","sc":1,"sum":"Intervenor labor union filed unfair labor practice charges with the National Labor Relations Board with respect to respondent hospital's rule prohibiting solicitation by its employees at all times \"in any area of the Hospital which is accessible to or utilized by the public,\" including the lobbies, gift shop, cafeteria, and entrances on the first floor, as well as corridors, sitting rooms, and public restrooms on …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"573 U.S. 513","y":2014,"id":"2013/12-1281","sc":1,"sum":"A case in which the Court further defined the limitations on the presidential powers granted by the Recess Appointments Clause.","sumSrc":"Oyez","by":{"1":"46"}},{"t":"case","label":"NLRB v. Pittsburgh S.S. Co.","cite":"340 U.S. 498","y":1951,"id":"scdb/1950-039","sc":1,"sum":"The judgment below is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"NLRB v. Walton Mfg. Co.","cite":"369 U.S. 404","y":1962,"id":"1961/77","sc":1,"sum":"The judgments are reversed and the cases are remanded to the Court of Appeals for reconsideration.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 27, 41","2":"34"}},{"t":"case","label":"Otay Mesa Prop., L.P. v. U.S. Dep’t of Interior","cite":"646 F.3d 914","y":2011,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/646/914/","by":{"1":"18"}},{"t":"case","label":"Pasternack v. Nat’l Transp. Safety Bd.","cite":"596 F.3d 836","y":2010,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/596/836/","by":{"1":"25","2":"32"}},{"t":"case","label":"Pension Benefit Guar. Corp. v. LTV Corp.","cite":"496 U.S. 633","y":1990,"id":"1989/89-390","sc":1,"sum":"The PBGC's restoration decision was not arbitrary and capricious or contrary to law under § 706(2)(A).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"47"}},{"t":"case","label":"Robinson v. Shell Oil Co.","cite":"519 U.S. 337","y":1997,"id":"1996/95-1376","sc":1,"sum":"Authored by Justice Clarence Thomas, the Court ruled that because the term \"employees,\" as used Title VII of the Civil Rights Act of 1964, includes former employees, Robinson may sue Shell for its allegedly retaliatory post-employment actions.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Sandstrom v. Montana","cite":"442 U.S. 510","y":1979,"id":"1978/78-5384","sc":1,"sum":"Because the jury may have interpreted the challenged presumption as conclusive, like the presumptions in Morissette v. United States, 342 U. S.246, and United States v. United States Gypsum Co., 438 U. S. 422, or as shifting the burden of persuasion, like that in Mullaney v. Wilbur, 421 U. S. 684, and because either interpretation would have violated the Fourteenth Amendment's requirement that the State prove every …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"op":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 19, 27","2":"11, 25, 32, 33"}},{"t":"case","label":"Singh v. Gonzales","cite":"495 F.3d 553","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/495/553/","sum":"Explaining that the “specific, cogent reasons” standard “is best understood as an application of the familiar [Chenery] principle”.","sumSrc":"brief:1","by":{"1":"27, 42","3":"13, 14"}},{"t":"case","label":"Singh v. Holder","cite":"753 F.3d 826","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/753/826/","by":{"1":"39"}},{"t":"case","label":"Steadman v. SEC","cite":"450 U.S. 91","y":1981,"id":"1980/79-1266","sc":1,"sum":"After an on-the-record hearing before an Administrative Law Judge and review by the Securities and Exchange Commission (SEC) in which the preponderance-of-the-evidence standard of proof was employed, the SEC held that petitioner had violated various antifraud provisions of the federal securities laws, and sanctions were imposed. Petitioner sought review in the Court of Appeals on the alleged ground, inter alia, that …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32, 39"}},{"t":"case","label":"T-Mobile South, LLC v. City of Roswell","cite":"574 U.S. 293","y":2015,"id":"2014/13-975","sc":1,"ar":1,"sum":"The Court held that the Telecommunications Act of 1996 does not require localities to provide reasons for their denial of construction applications in the written denial notification as long as the reasons appear in some other sufficiently clear written record.","sumSrc":"Oyez","by":{"1":"passim"}},{"t":"case","label":"Tyler v. Cain","cite":"533 U.S. 656","y":2001,"id":"2000/00-5961","sc":1,"sum":"The Court held that the Cage rule was not \"made retroactive to cases on collateral review by the Supreme Court.\" Justice Thomas wrote for the Court that \"[b]ecause 'made' means 'held'...it is clear that the Cage rule has not been 'made retroactive to cases on collateral review by the Supreme Court.' Cage itself does not hold that it is retroactive.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"United States v. Carlo Bianchi & Co.","cite":"373 U.S. 709","y":1963,"id":"1962/529","sc":1,"sum":"In a suit on a government contract, apart from questions of fraud, determination of the finality to be attached to a departmental decision on a question arising under a \"disputes\" clause must rest solely on consideration of the record before the department, and no new evidence may be received or considered. Pp. 709-718. 157 Ct. Cl. -, judgment vacated and cause remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 34"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31, 33"}},{"t":"case","label":"Unitherm Food Sys., Inc. v. Swift-Eckrich, Inc.","cite":"546 U.S. 394","y":2006,"id":"2005/04-597","sc":1,"sum":"The Court ruled that a party must renew its motion for judgment under Rule 50(b) if the motion is to be the basis for an appeal.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Universal Camera Corp. v. NLRB","cite":"340 U.S. 474","y":1951,"id":"scdb/1950-038","sc":1,"sum":"The National Labor Relations Board ordered petitioner to reinstate with back pay an employee found to have been discharged because he gave certain testimony in another proceeding under the National Labor Relations Act. The evidence as to the reason for his discharge was conflicting; and the Board overruled its examiner's findings of fact and his recommendation that the proceedings be dismissed. In decreeing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim"}},{"t":"case","label":"Wainwright v. Witt","cite":"469 U.S. 412","y":1985,"id":"1984/83-1427","sc":1,"sum":"Respondent was tried by a jury in a Florida state court and convicted of first-degree murder. In accordance with the jury's recommendation, he was sentenced to death. On appeal, respondent claimed that several prospective jurors had been improperly excluded for cause because of their opposition to capital punishment, in violation of the decision in Witherspoon v. Illinois, 391 U. S. 510, but the Florida Supreme …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26","2":"34"}},{"t":"case","label":"West v. Gibson","cite":"527 U.S. 212","y":1999,"id":"1998/98-238","sc":1,"op":1,"sum":"The Court held that the Equal Employment Opportunity Commission possess the legal authority to require federal agencies to pay compensatory damages when they discriminate in violation of Title VII of Civil Rights Act of 1964.","sumSrc":"Oyez","by":{"1":"48"}},{"t":"case","label":"Woodby v. INS","cite":"385 U.S. 276","y":1966,"id":"1966/40","sc":1,"sum":"No deportation order may be entered unless the Government proves by clear, unequivocal, and convincing evidence that the facts alleged as grounds for deportation are true.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 30"}},{"t":"usc","label":"5 U.S.C. § 556","url":"https://www.law.cornell.edu/uscode/text/5/556","subs":["(d)"],"by":{"1":"22"}},{"t":"law","label":"Pub. L. No. 109-13","url":"https://www.govinfo.gov/link/plaw/109/public/13","by":{"1":"passim"}},{"t":"reg","label":"8 C.F.R. § 1003.1","url":"https://www.ecfr.gov/current/title-8/section-1003.1","subs":["(d)(1)","(d)(3)(i)"],"by":{"1":"6, 5, 6"}},{"t":"reg","label":"Board of Immigration Appeals: Procedural Reforms To Improve Case Management, 67 Fed. Reg. 54,878","url":"https://www.govinfo.gov/link/fr/67/54878","by":{"1":"27"}},{"t":"case","label":"Alvarez Lagos v. Barr","cite":"927 F.3d 236","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/927/236/","by":{"2":"47"}},{"t":"case","label":"Castenada-Castillo v. Gonzales","cite":"488 F.3d 17","y":2007,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/488/17/","by":{"2":"47"}},{"t":"case","label":"Doe v. Att’y Gen. of the United States","cite":"956 F.3d 135","y":2020,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/956/135/","by":{"2":"49"}},{"t":"case","label":"Fla. Power & Light Co. v. Lorion","cite":"470 U.S. 729","y":1985,"id":"1984/83-703","sc":1,"sum":"Section 2239 vests in the courts of appeals initial subject-matter jurisdiction over Commission orders denying citizen petitions made pursuant to Commission rules.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32","3":"18, 19"}},{"t":"case","label":"Francis v. Franklin","cite":"471 U.S. 307","y":1985,"id":"1984/83-1590","sc":1,"sum":"The instruction on intent, when read in the context of the jury charge as a whole, violated the Fourteenth Amendment's requirement that the State prove every element of a criminal offense beyond a reasonable doubt. Sandstrom v. Montana, supra.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Ghebremedhin v. Aschroft","cite":"392 F.3d 241","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/392/241/","by":{"2":"47"}},{"t":"case","label":"Gulf States Utilities Co. v. Fed. Power Comm’n","cite":"411 U.S. 747","y":1973,"id":"1972/71-1178","sc":1,"sum":"Following petitioner's application under § 204 of the Federal Power Act to respondent Federal Power Commission (FPC) for authorization of a bond issue, two intervening cities opposed the authorization on the ground that the proceeds of the bond issue would be used to finance or refinance certain anticompetitive activities in violation of the antitrust laws, the Federal Power Act, and the Public Utility Holding …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"32"}},{"t":"case","label":"Lin v. Ashcroft","cite":"385 F.3d 748","y":2004,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/385/748/","sum":"Holding that the return of a Chinese asylum applicant’s daughter did not undermine the applicant’s well-founded fear of a forced abortion.","sumSrc":"brief:2","by":{"2":"43, 44"}},{"t":"case","label":"Loho v. Mukasey","cite":"531 F.3d 1016","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1016/","by":{"2":"39"}},{"t":"case","label":"St. Mary’s Honor Center v. Hicks","cite":"509 U.S. 502","y":1993,"id":"1992/92-602","sc":1,"sum":"The trier of fact's rejection of an employer's asserted reasons for its actions does not entitle a plaintiff to judgment as a matter of law.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"33"}},{"t":"case","label":"Watson v. Geren","cite":"569 F.3d 115","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/569/115/","by":{"2":"47"}},{"t":"case","label":"Yusupov v. Att’y Gen. of the United States","cite":"650 F.3d 968","y":2011,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/650/968/","by":{"2":"47"}},{"t":"case","label":"Zhao v. Gonzales","cite":"404 F.3d 295","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/404/295/","by":{"2":"47"}},{"t":"case","label":"Zhu v. Gonzales","cite":"493 F.3d 588","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/493/588/","by":{"2":"49"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"136 S. Ct. 2117","y":2016,"id":"2015/15-415","sc":1,"ar":2,"sum":"The Court held that, because the Department of Labor did not give adequate reasons for altering its position on whether service advisors are exempt from overtime compensation under the Fair Labor Standards Act (FLSA), the case should be remanded for reinterpretation that does not give controlling weight to the Department’s 2011 position.","sumSrc":"Oyez","by":{"3":"14"}},{"t":"case","label":"FCC v. Pottsville Broad. Co.","cite":"309 U.S. 134","y":1940,"id":"scdb/1939-099","sc":1,"op":1,"sum":"1. A lower court's interpretation of its own mandate does not bind this Court.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"18"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","stext":{"head":"§701. Application; definitions","paras":[[0,"(a) This chapter applies, according to the provisions thereof, except to the extent that—"],[1,"(1) statutes preclude judicial review; or"],[1,"(2) agency action is committed to agency discretion by law."],[0,"(b) For the purpose of this chapter—"],[1,"(1) \"agency\" means each authority of the Government of the United States, whether or not it is within or subject to review by another agency, but does not include—"],[2,"(A) the Congress;"],[2,"(B) the courts of the United States;"],[2,"(C) the governments of the territories or possessions of the United States;"],[2,"(D) the government of the District of Columbia;"],[2,"(E) agencies composed of representatives of the parties or of representatives of organizations of the parties to the disputes determined by them;"],[2,"(F) courts martial and military commissions;"],[2,"(G) military authority exercised in the field in time of war or in occupied territory; or"],[2,"(H) functions conferred by sections 1738, 1739, 1743, and 1744 of title 12; subchapter II of chapter 471 of title 49; or sections 1884, 1891–1902, and former section 1641(b)(2), of title 50, appendix; 1 and"],[1,"(2) \"person\", \"rule\", \"order\", \"license\", \"sanction\", \"relief\", and \"agency action\" have the meanings given them by section 551 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/701?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§701. Application; definitions","tname":"Government Organization and Employees","by":{"3":"14"}},{"t":"reg","label":"8 C.F.R. § 1208.13","url":"https://www.ecfr.gov/current/title-8/section-1208.13","subs":["(b)(1)(ii)"],"by":{"3":"22"}}]};